#include "studio_render_state_restore_submit_candidate.h"
#include <array>
#include <cassert>
#include <cstdio>
struct Services{unsigned suppression;bool queued;unsigned direct=0,published=0,acquired=0;std::array<uint32_t,4096> replacement{};unsigned suppressed(){return suppression;}bool queueEnabled(){return queued;}void flush(){assert(false);}void directState(unsigned key,unsigned value){assert(key==8&&value==3);++direct;}void publish(uint32_t* block){assert(block[0]==2&&block[2]==0);++published;}uint32_t* acquire(unsigned header){assert(header==1);++acquired;replacement[0]=header;return replacement.data();}};
int main(){unsigned cases=0;for(unsigned suppression:{0u,1u,256u})for(bool queued:{false,true})for(bool equal:{false,true})for(unsigned remaining:{2u,3u}){std::array<uint32_t,16> cache{};cache[8]=equal?3:99;std::array<uint32_t,4096> block{};block[0]=1;block[1]=999;StudioDeviceQueueStateCandidate queue{block.data(),block.data()+2,remaining};StudioRenderStateOwnerCandidate owner{cache.data(),&queue};Services services{suppression,queued};studioRenderStateRestoreSubmitCandidate(owner,8,3,services);if(static_cast<uint8_t>(suppression)){assert(cache[8]==(equal?3u:99u)&&!services.direct&&!services.acquired&&!services.published&&queue.remaining==remaining);}else if(!queued){assert(cache[8]==3&&services.direct==1&&!services.acquired&&queue.remaining==remaining);}else{assert(cache[8]==3&&!services.direct);if(remaining==2){assert(services.acquired==1&&services.published==1&&queue.remaining==4092&&queue.cursor==services.replacement.data()+4&&services.replacement[1]==1&&services.replacement[2]==8&&services.replacement[3]==3);}else{assert(!services.acquired&&!services.published&&queue.remaining==0&&queue.cursor==block.data()+5&&block[2]==1&&block[3]==8&&block[4]==3);}}++cases;}std::printf("restore_render_state_candidate_cases=%u passed\n",cases);}
